cd /bench/home/work
python3 - <<'EOF'
import re, subprocess, os

func_re = re.compile(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\s*\(')
funcs = []
for root, dirs, files in os.walk('internal'):
    for fn in files:
        if fn.endswith('.go') and not fn.endswith('_test.go'):
            path = os.path.join(root, fn)
            with open(path) as f:
                for i, line in enumerate(f, 1):
                    m = func_re.match(line)
                    if m:
                        name = m.group(1)
                        if name in ('init',):
                            continue
                        funcs.append((name, path, i))

results = []
for name, path, line in funcs:
    # search whole repo for calls "<something>.name(" or bare "name(" 
    pattern = re.escape(name) + r'\('
    try:
        out = subprocess.run(['grep', '-rEn', pattern, '--include=*.go', '.'], capture_output=True, text=True, timeout=30)
    except Exception:
        continue
    lines = [l for l in out.stdout.splitlines() if '_test.go' not in l]
    # exclude the definition line itself
    count = 0
    for l in lines:
        fpath = l.split(':',1)[0]
        # crude: subtract lines that are function definitions of same name
        if re.search(r'func\s+(\([^)]*\)\s*)?'+re.escape(name)+r'\(', l):
            continue
        count += 1
    results.append((count, name, path, line))

results.sort(reverse=True)
for r in results[:20]:
    print(r)
EOF

